<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import MainLayout from '@/components/MainLayout.vue'
import request from '@/utils/request'
import { useRoute } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
type Row=Record<string,any>
const auth=useAuthStore(),tab=ref(['works','purchases','stock','postings'].includes(String(useRoute().query.tab))?String(useRoute().query.tab):'works'),error=ref(''),message=ref(''),busy=ref(false)
const works=ref<Row[]>([]),purchases=ref<Row[]>([]),balances=ref<Row[]>([]),postings=ref<Row[]>([]),warehouses=ref<Row[]>([]),locations=ref<Row[]>([])
const selected=ref<Row>(),materials=ref<Row[]>([]),trace=ref<Row[]>([]),purchaseLines=ref<Row[]>([])
const warehouse=ref<number|''>(''),modal=ref(false),action=ref(''),target=ref<Row>(),form=reactive<Row>({warehouse_id:'',location_id:''})
const canPost=computed(()=>[5,9].includes(Number(auth.currentUser?.roleId)))
const allowedLocations=computed(()=>locations.value.filter(l=>Number(l.warehouse_id)===Number(form.warehouse_id)))
const kindNames:Row={ISSUE:'生产领料',RECEIPT:'完工入库',PURCHASE:'采购收货',SHIP:'销售发货'}
const titles:Row={issue:'按冻结BOM整批领料',receive:'成品整批入库',purchase:'采购整批收货',ship:'销售整单发货'}
const status=(r:Row)=>r.shipment_no?'已发货':r.receipt_no?'成品已入库':r.status==='PRODUCTION_COMPLETED'?'生产完成待入库':r.issue_no?'已领料，可生产':'待领料'
async function load(){try{error.value='';const result=await Promise.all(['/fulfillment/work-orders','/fulfillment/purchases','/fulfillment/stock','/fulfillment/postings','/foundation/warehouses','/fulfillment/locations'].map(p=>request.get<Row[]>(p)));[works.value,purchases.value,balances.value,postings.value,warehouses.value,locations.value]=result;if(selected.value)await show(selected.value)}catch(e:any){error.value=e.message}}
async function show(row:Row){selected.value=row;try{materials.value=await request.get(`/fulfillment/work-orders/${row.id}/materials`,{params:warehouse.value?{warehouse:warehouse.value}:{}});trace.value=await request.get(`/fulfillment/work-orders/${row.id}/trace`)}catch(e:any){error.value=e.message}}
async function showPurchase(row:Row){try{purchaseLines.value=await request.get(`/fulfillment/purchases/${row.id}/items`)}catch(e:any){error.value=e.message}}
function open(kind:string,row:Row){error.value='';action.value=kind;target.value=row;form.warehouse_id=warehouse.value||'';form.location_id='';modal.value=true}
async function submit(){if(!target.value)return;busy.value=true;try{const row=target.value;const path=action.value==='purchase'?`/fulfillment/purchases/${row.id}/receive`:action.value==='ship'?`/fulfillment/orders/${row.order_id}/ship`:`/fulfillment/work-orders/${row.id}/${action.value}`;const receipt=await request.post<Row>(path,form);modal.value=false;message.value=`过账成功，凭据 ${receipt.document_no}；库存与流水已同步。`;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><MainLayout>
  <div class="flex justify-between mb-5 gap-4"><div><p class="text-sm text-blue-600">生产、质量与仓储</p><h1 class="text-2xl font-bold mt-1">生产与仓储闭环</h1><p class="text-gray-500 text-sm mt-2">来料检验 → 采购收货 → 工单领料 → 制造与质检 → 成品入库 → 出货检验 → 销售发货</p></div><router-link to="/manufacturing" class="self-start bg-white border rounded-lg px-4 py-2">进入制造与质量放行</router-link></div>
  <p v-if="error" role="alert" class="bg-red-50 text-red-700 p-3 rounded-lg mb-4">{{error}}</p><p v-if="message" role="status" class="bg-green-50 text-green-700 p-3 rounded-lg mb-4">{{message}}</p>
  <div class="flex flex-wrap gap-2 mb-4"><button v-for="t in [{id:'works',name:'工单领料与发货'},{id:'purchases',name:'采购收货'},{id:'stock',name:'真实库存余额'},{id:'postings',name:'过账凭据'}]" :key="t.id" class="px-4 py-2 rounded-lg" :class="tab===t.id?'bg-blue-600 text-white':'bg-white border'" @click="tab=t.id">{{t.name}}</button><button class="ml-auto bg-white border rounded-lg px-4 py-2" @click="load">刷新</button></div>
  <section v-if="tab==='works'" class="bg-white border rounded-xl overflow-hidden"><div class="p-4 flex gap-3 items-center border-b"><h2 class="font-semibold">制造工单</h2><label class="ml-auto text-sm">领料仓库筛选 <select v-model="warehouse" class="border rounded p-2 ml-2" @change="selected&&show(selected)"><option value="">全部仓库</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.warehouse_name}}</option></select></label></div><div class="overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-3">工单 / 来源订单</th><th>产品</th><th>计划 / 完成</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in works" :key="r.id" class="border-t"><td class="p-3">{{r.code}}<p class="text-gray-400 mt-1">{{r.order_no||'独立计划'}}</p></td><td>{{r.product_name}}</td><td>{{r.quantity}} / {{r.completed_quantity}}</td><td>{{status(r)}}</td><td class="space-x-3 p-3"><button class="text-blue-600" @click="show(r)">用料与追溯</button><template v-if="canPost"><button v-if="!r.issue_no&&r.status!=='PRODUCTION_COMPLETED'" class="text-blue-600" @click="open('issue',r)">领料扣库</button><button v-if="r.status==='PRODUCTION_COMPLETED'&&!r.receipt_no" class="text-blue-600" @click="open('receive',r)">成品入库</button><button v-if="r.receipt_no&&!r.shipment_no&&r.order_id" class="text-blue-600" @click="open('ship',r)">检验后发货</button></template></td></tr><tr v-if="!works.length"><td colspan="5" class="text-center text-gray-400 p-10">暂无新制造工单，请先在“制造与质量放行”创建并下发工单。</td></tr></tbody></table></div></section>
  <section v-if="tab==='works'&&selected" class="bg-white border rounded-xl p-5 mt-5"><h2 class="font-semibold mb-3">{{selected.code}} · 冻结用料与库存齐套</h2><p class="text-sm text-gray-500 mb-4">需求按下发时BOM冻结。领料后材料已投入生产，当前库存不足不再作为该工单缺料。</p><div class="overflow-auto"><table class="w-full text-sm text-left"><thead><tr><th class="p-2">原材料</th><th>需求数量</th><th>当前可用</th><th>缺料</th><th>状态</th></tr></thead><tbody><tr v-for="r in materials" :key="r.id" class="border-t"><td class="p-2">{{r.material_name}}<span class="text-xs text-gray-400 ml-2">{{r.material_code}}</span></td><td>{{r.required_quantity}} {{r.unit}}</td><td>{{r.available_quantity}}</td><td :class="Number(r.shortage_quantity)>0?'text-red-600':'text-green-700'">{{r.shortage_quantity}}</td><td>{{r.issued?'已领料':'待领料'}}</td></tr></tbody></table></div><h3 class="font-semibold mt-6 mb-3">批次与流水追溯</h3><div class="overflow-auto"><table class="w-full text-sm text-left"><thead><tr><th class="p-2">凭据</th><th>物料</th><th>批次</th><th>方向</th><th>数量</th><th>变动前 → 后</th></tr></thead><tbody><tr v-for="r in trace" :key="r.id" class="border-t"><td class="p-2">{{r.source_order_no}}</td><td>{{r.material_name}}</td><td>{{r.lot_no||'历史无批次'}}</td><td>{{r.transaction_type==='IN'?'入库':'出库'}}</td><td>{{r.quantity}}</td><td>{{r.before_quantity}} → {{r.after_quantity}}</td></tr><tr v-if="!trace.length"><td colspan="6" class="text-center text-gray-400 p-6">尚无关联库存流水。</td></tr></tbody></table></div></section>
  <section v-if="tab==='purchases'" class="bg-white border rounded-xl overflow-hidden"><div class="p-4 border-b text-sm text-gray-500">采购单先在采购管理中新增、提交并审批，再执行来料检验；本阶段按整单整批入库。</div><div class="overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-3">采购单</th><th>供应商</th><th>状态</th><th>入库凭据</th><th>操作</th></tr></thead><tbody><tr v-for="r in purchases" :key="r.id" class="border-t"><td class="p-3">{{r.po_no}}</td><td>{{r.supplier_name}}</td><td>{{({DRAFT:'草稿',SUBMITTED:'待审批',APPROVED:'已审批',COMPLETED:'已完成',CANCELLED:'已取消',PARTIAL_RECEIVED:'历史部分收货'} as Row)[r.status]||r.status}}</td><td>{{r.receipt_no||'尚未入库'}}</td><td class="space-x-3"><button class="text-blue-600" @click="showPurchase(r)">明细</button><button v-if="canPost&&r.status==='APPROVED'&&!r.receipt_no" class="text-blue-600" @click="open('purchase',r)">质检后收货</button></td></tr><tr v-if="!purchases.length"><td colspan="5" class="text-gray-400 text-center p-10">暂无采购单。请在采购管理创建实际采购需求。</td></tr></tbody></table></div><div v-if="purchaseLines.length" class="p-4 border-t"><h2 class="font-semibold mb-3">采购明细与整批检验数量</h2><p v-for="r in purchaseLines" :key="r.id" class="py-2">{{r.material_name}}：采购 {{r.quantity}} {{r.unit}}，已收 {{r.received_quantity}}</p></div></section>
  <section v-if="tab==='stock'" class="bg-white border rounded-xl overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-3">物料</th><th>仓库</th><th>库位</th><th>批次</th><th>余额</th><th>最后更新</th></tr></thead><tbody><tr v-for="r in balances" :key="r.id" class="border-t"><td class="p-3">{{r.material_name}}<p class="text-gray-400 text-xs">{{r.material_code}}</p></td><td>{{r.warehouse_name}}</td><td>{{r.location_name||'历史未指定'}}</td><td>{{r.lot_no||'历史无批次'}}</td><td>{{r.quantity}} {{r.unit}}</td><td>{{r.last_update_time}}</td></tr><tr v-if="!balances.length"><td colspan="6" class="text-center text-gray-400 p-10">库存为空。实际采购收货后会显示余额。</td></tr></tbody></table></section>
  <section v-if="tab==='postings'" class="bg-white border rounded-xl overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-3">凭据</th><th>业务</th><th>仓库</th><th>经办人</th><th>过账时间</th></tr></thead><tbody><tr v-for="r in postings" :key="r.id" class="border-t"><td class="p-3">{{r.document_no}}</td><td>{{kindNames[r.kind]}}</td><td>{{r.warehouse_name}}</td><td>{{r.actor_name}}</td><td>{{r.created_at}}</td></tr><tr v-if="!postings.length"><td colspan="5" class="text-gray-400 text-center p-10">暂无过账凭据。</td></tr></tbody></table></section>
  <div v-if="modal" class="fixed inset-0 bg-black/40 z-[90] flex items-center justify-center p-6"><form class="bg-white rounded-xl p-6 w-full max-w-lg" @submit.prevent="submit"><h2 class="text-xl font-bold mb-3">{{titles[action]}}</h2><p class="text-gray-500 text-sm mb-4">{{target?.code||target?.po_no}} · 提交后系统校验来源和库存，成功后凭据保留以供追溯。</p><p v-if="error" role="alert" class="text-red-600 mb-3">{{error}}</p><label class="block text-sm mb-1" for="posting-warehouse">仓库</label><select id="posting-warehouse" v-model="form.warehouse_id" required class="border rounded-lg p-2 w-full mb-4" @change="form.location_id=''"><option value="">请选择</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.warehouse_name}}</option></select><template v-if="['receive','purchase'].includes(action)"><label for="posting-location" class="block text-sm mb-1">入库库位</label><select id="posting-location" v-model="form.location_id" required class="border rounded-lg p-2 w-full mb-4"><option value="">请选择该仓库库位</option><option v-for="l in allowedLocations" :key="l.id" :value="l.id">{{l.location_name}} · {{l.location_code}}</option></select></template><p class="bg-blue-50 text-blue-700 text-sm p-3 rounded-lg mb-5">{{action==='issue'?'按冻结BOM一次领齐本工单所需原材料，缺任一物料则整单不扣库。':action==='ship'?'仅从本订单对应的已入库成品批次扣库；必须先通过出货检验。':action==='purchase'?'采购单必须已审批并通过整批来料检验；系统生成原料批次。':'所有工序完成放行后，系统生成工单成品批次并增加库存。'}}</p><div class="flex justify-end gap-3"><button type="button" @click="modal=false">取消</button><button :disabled="busy" class="bg-blue-600 text-white rounded-lg px-4 py-2">{{busy?'正在过账…':'确认过账'}}</button></div></form></div>
</MainLayout></template>
